UPDATE companies SET description='Great Blue Heron Furniture operates from Manchaca, Texas, where it was founded in 1991.

The shop produces custom leather furniture, including sofas, chairs, ottomans, dining tables, and hand-carved wood pieces. Its product line spans armchairs, loveseats, sectionals, recliners, and specialty items such as hacienda tables and trophy-room furnishings. Current lead time for upholstery runs seven to nine weeks.

The company states its goal is to set the standard in quality and design for western and contemporary western furniture, offering products that are truly unique. A made-for-you custom design service guides clients from vision to finished piece, whether for a single statement chair or a fully furnished home.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Custom furniture design", "Leather upholstery", "Hand-carved woodwork", "Western furniture manufacturing", "Made-to-order production"], "industries": ["High-end residential", "Trophy room/ranch furnishings", "Hospitality furnishings"], "materials": ["Leather", "Walnut", "Cashmere", "Buffalo leather", "Wood"], "equipment": [], "volume": "", "lead_time": "7-9 weeks for upholstery", "tolerances": "", "built_on": ["Custom design consultation for each project", "Specialty in western and contemporary western furniture", "Hand-carved woodwork and leather upholstery", "Client galleries demonstrating installed projects", "Upholstery lead time of 7-9 weeks"], "facts_used": ["Founded 1991 -> db", "Headquarters in Manchaca, Texas -> db", "Custom leather furniture manufacturer -> /", "Western and contemporary western furniture specialty -> /", "Made-for-you custom design service -> /", "Current lead time on upholstery 7-9 weeks -> /", "Client galleries include Croell Estate, Bailey Trophy Room, Parkers -> /", "Products include sofas, chairs, tables, hand-carved pieces -> /", "Materials: leather, walnut, cashmere, buffalo leather -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Buy & Design Custom Leather Furniture USA", "founded_year": "1991", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='great-blue-heron-furniture' AND approved AND profile IS NULL;
UPDATE companies SET description='Great Divide Fabrication LLC operates as Great Divide Services in Buffalo, Wyoming. The business traces its roots to 2011 in company records, though founder Erik Burden states he launched the service operation in 2018 after progressing from apprentice to journeyman and manager. Burden, a master mechanical technician, owns and leads the company with his wife Jenn and their two sons living locally.

The shop provides heating, ventilation, and air-conditioning services for homes and businesses, including furnace and heat-pump installation, ductless mini-split systems, rooftop units, and 24-hour emergency repair. In addition to HVAC work, the team runs a custom sheet-metal fabrication operation, producing decorative tin work and fabricated metal components on a per-project basis. They also sell metal, piping, and miscellaneous supplies directly to walk-in customers. The fabrication side quotes per job after an on-site appointment, with rates varying by complexity.

Burden emphasizes that a collaborative work environment and a commitment to craftsmanship set the operation apart.', certifications=ARRAY[]::text[], profile='{"capabilities": ["HVAC installation and service", "Heating system installation (furnaces, heat pumps, infrared garage heaters)", "Cooling system installation (split systems, ductless mini splits, rooftop units)", "Custom sheet metal fabrication", "Decorative tin work", "Gas piping", "24-hour emergency repair", "Annual maintenance service calls", "Residential metal and piping sales"], "industries": ["Residential", "Commercial", "HVAC"], "materials": ["Metal", "Piping"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["24-hour emergency HVAC service", "Custom sheet metal fabrication quoted per project", "Decorative tin work customization", "Owner is a master mechanical technician with 15+ years trade experience", "Direct sales of metal, piping, and supplies to walk-in customers"], "facts_used": ["Location: Buffalo, Wyoming -> db, /, /about", "Founded 2011 (database) / launched 2018 (website) -> db, /about", "Owner: Erik Burden, master mechanical technician -> /, /about", "Services: HVAC heating, cooling, 24-hour service, gas piping -> /, /services", "Custom sheet metal fabrication and decorative tin work -> /, /services", "Residential sales of metal, piping, miscellaneous items -> /, /services", "Serves residential and commercial customers in Buffalo and surrounding communities -> /, /services", "Owner''s background: apprentice to journeyman to manager to owner, 15+ years experience -> /about", "No certifications, equipment, volume, lead time, tolerances, cage code, min order, export compliance, languages, or social links stated -> all pages"], "company_type": "Contract manufacturer / job shop", "makes_products": "yes", "type_evidence": "custom sheet metal fabrication; We have talented employees who are more than happy to help customize material to fill your needs", "founded_year":