UPDATE companies SET description='Green Mountain Furniture has operated in Ossipee, New Hampshire, since 1975. The store takes its name from the mountain range that rises behind the property, and its 40,000-square-foot showroom spans multiple floors in a building noted for its creaking wood floors and a layout that changes regularly.

The business functions as a full-line home furnishings retailer. Its showroom carries living-room, bedroom, dining, home-office, and kitchen furniture, along with mattresses, adjustable bases, area rugs, lighting, window treatments, bath décor, and decorative accessories. Brands represented include Craftmaster, Flexsteel, and Best Home.

The product mix spans upholstered collections (sofas, sectionals, recliners, sleeper sofas), wood case goods, bedding, and accent pieces. Shoppers can browse in person or request product dimensions and SKU listings for specific collections such as Craftmaster’s SS, F9, M9, C9, and L9 series or Flexsteel’s Thornton and Catalina groups.

The company positions itself on an experience-first model: sales staff are not commissioned, the showroom encourages hands-on testing — sitting, reclining, lying on beds — and two warranty programs are highlighted, a Guardsman five-year fabric and leather protection plan and a 100-night sleep guarantee on mattresses.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Furniture retail", "Delivery service", "Old furniture removal", "Mattress sleep trial", "Fabric and leather protection plans"], "industries": ["Residential furniture retail", "Home furnishings"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": [], "facts_used": ["Founded 1975 -> db", "Headquarters Ossipee, NH -> db", "40,000 sq ft showroom -> page /", "Named for mountain range -> page /", "Brands: Craftmaster, Flexsteel, Best Home -> page /", "Product collections listed (SS, F9, M9, C9, L9, Thornton, Catalina) -> db products", "Delivery with removal service -> db capabilities", "Non-commission sales staff -> page /", "Guardsman 5-year warranty -> page /", "100-night mattress sleep guarantee -> page /"], "company_type": "Retailer", "makes_products": "no", "type_evidence": "Our website is intended to give you a virtual feel for the styles and variety of pieces we carry... we encourage you to take the drive and come see our store in person.", "founded_year": "1975", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='green-mountain-furniture' AND approved AND profile IS NULL;
UPDATE companies SET description='Moser Engineering operates from a 100,000-square-foot facility in Portland, Indiana. The company was founded in 1986 by Greg Moser, who initially launched the business to support his own drag-racing habit at the Muncie strip. Today it remains family owned and operated.

The shop forges, heat-treats, and machines U.S. steel sourced from domestic mills to produce custom axles, complete rear-end assemblies, differential options, brake packages, and chassis/suspension components. Product lines include the Muscle Pak rear assemblies, circle-track/oval packages, and applications for GM, Ford, and Mopar platforms. Most custom orders ship in two business days or less.

The company''s own race team campaigns two rigs and multiple cars, putting new components through on-track validation before release.

Moser Engineering cites three pillars for its approach: domestic manufacturing with full process control, rapid turnaround enabled by that control, and direct racing experience that informs product development. Staff includes current and former racers and builders, many with decades of tenure.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Custom axle manufacturing", "Complete rear end assembly", "Forging", "Heat treating", "CNC machining", "Ring and pinion setup", "Differential assembly", "Brake package installation", "Chassis/suspension component fabrication", "Circle track/oval package assembly", "Drag racing component manufacturing", "Muscle Pak rear assembly", "Axle packaging", "Housing service parts", "Axle service parts"], "industries": ["Drag racing", "Circle track racing", "Street rod building", "Automotive aftermarket", "Jeep/truck accessories", "Project car restoration"], "materials": ["U.S. steel", "Alloy steel", "Chrome moly (4130)"], "equipment": [], "volume": "", "lead_time": "Most custom orders ship in two business days or less", "tolerances": "", "built_on": ["Custom orders ship in two business days or less", "Entire manufacturing process controlled in-house (forge, heat treat, machine)", "U.S. steel sourced exclusively from U.S. mills", "Own race team tests products on track before release", "Family owned and operated since 1986"], "facts_used": ["Founded in 1986 by Greg Moser -> /about", "Family owned and operated -> /about", "100,000 sq ft facility in Portland, Indiana -> /about", "Started to support Greg''s racing habit -> /about", "Forge, heat treat, machine U.S. steel from U.S. mills -> /about", "Custom axles, complete rear ends, differential options, brake packages, chassis/suspension -> /about, /", "Muscle Pak rear assemblies, circle-track/oval packages, GM/Ford/Mopar applications -> /", "Custom orders ship in two business days or less -> /about", "Own race team with two rigs and multiple cars -> /about", "Staff includes current/former racers and builders -> /about", "Products: axles for Jeep/truck, drag floater setups, project cars -> /about", "40 years of Moser Engineering (as of page date) -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "We use high-end technology and precision machinery to make custom axles, complete rear ends, and more at our facility in Portland, Indiana.", "founded_year": "1986", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Family-owned"]}'::jsonb, updated_at=now() WHERE slug='greg-moser-engineering-inc' AND approved AND profile IS NULL;
UPDATE companies SET description='Grillo & Co operates a woodworking workshop in Golden, Colorado, where founder John Grillo produces custom furniture on commission. Grillo trained at the Thomas Chippendale International School of Furniture in Scotland, where his work earned the Richard Demarco Prize and recognition in Furniture & Cabinetmaking Magazine and The Scottish Times. A member of the Fine Furniture Guild, he established the studio to blend contemporary and traditional techniques in one-off pieces for homes and workplaces.

The shop designs and hand-builds freestanding furniture including dining tables, writing desks, console tables, side tables, and cabinets. Each project begins with a client consultation and 3D sketches, followed by a 50% deposit and fabrication using joinery such as dovetails, tambour doors, and parquetry. Materials range from domestic hardwoods — walnut, maple, cherry, figured cherry — to exotic veneers like pepperwood and burl walnut.

Grillo & Co serves residential and commercial clients seeking heirloom-quality pieces. Past commissions include a walnut coffee table for a homeowner, multiple pieces for a repeat collector, and unusual custom projects for a client who returned for a second order. The company also offers home and office visits to match existing décor, indicating an interior-design adjacent clientele.

The firm emphasizes award-winning craftsmanship, direct designer-to-client pricing, and freedom from commercial supply-chain delays. Grillo’s Chippendale training and guild membership underpin a design philosophy that treats furniture as functional art, with every detail — down to dovetail style — tailored to the buyer.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Custom furniture design", "Handcrafted woodworking", "Commission-based manufacturing", "3D design visualization", "Dovetail joinery", "Tambour door construction", "Parquetry and inlay", "Wood selection and sourcing", "On-site consultation visits", "Progress updates and workshop access"], "industries": ["Residential furniture", "Commercial office furniture", "Interior design", "Custom woodworking"], "materials": ["Walnut", "Maple", "Cherry", "Figured cherry", "Burl walnut", "Birds-eye maple", "Yew wood", "Pepperwood veneer"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Richard Demarco Prize-winning design (round walnut dining table)", "Thomas Chippendale International School of Furniture training", "Fine Furniture Guild membership", "3D sketch review and client collaboration before build", "Handcrafted in Golden, Colorado with no supply-chain constraints"], "facts_used": ["Workshop in Golden, Colorado -> /", "John Grillo founder and master woodworker -> /", "Trained at Thomas Chippendale International School of Furniture -> /about", "Received Richard Demarco Prize -> /about", "Member of Fine Furniture Guild -> /about", "Custom design and hand make each piece to exact specifications -> /", "Commission-based with 50% deposit -> /services", "3D sketches and pricing options -> /services", "Home/office visits offered -> /services", "Materials: walnut, maple, cherry, figured cherry, burl walnut, birds-eye maple, yew wood, pepperwood veneer -> /, /about", "Joinery: dovetails, tambour doors, parquetry -> /", "No supply-chain constraints -> /services", "Customer reviews: Spencer P., Kelsey M., Troy F. -> /services", "Headquarters: Golden, Colorado -> db"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Grillo and Co creates beautiful bespoke furniture for your home or workplace. Operating almost entirely by commission, we custom design and hand make each piece to your exact specifications at our workshop in Golden, Colorado.", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='grillo-co' AND approved AND profile IS NULL;
UPDATE companies SET description='Groves Bros. was founded in 2001 in Mineral Wells, Texas, where it continues to operate as a manufacturer of handcrafted fabrics.

The workshop produces fabrics using techniques inspired by age-old Venetian traditions, with each piece crafted by hand to ensure uniqueness. The process emphasizes artisanal methods rather than mass production, though details on facility size, headcount, or annual volume are not publicly specified. The company''s online presence includes a gallery and tools to explore fabrics by color and pattern.

Groves Bros. distinguishes itself through its commitment to handcrafted individuality and Venetian-inspired craftsmanship, positioning its products as timeless, one-of-a-kind textiles made domestically in Texas.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Handcrafted fabric production", "Venetian-inspired textile techniques", "Custom color and pattern selection", "Drapery fabric manufacturing", "Upholstery fabric manufacturing", "Wall covering fabric manufacturing"], "industries": ["Drapery", "Upholstery", "Wall covering"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Handcrafted premier fabrics", "Each fabric unique", "Venetian-inspired techniques", "Made in Mineral Wells, Texas"], "facts_used": ["Founded in 2001 -> db", "Headquartered in Mineral Wells, Texas -> db and page /", "Handcrafts premier fabrics using Venetian-inspired techniques -> page /", "Each fabric is unique -> page /", "Serves drapery, upholstery, and wall covering projects -> page /", "Offers gallery and color/pattern exploration -> page /", "25 years of experience stated -> page /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "we craft timeless premier fabrics by hand", "founded_year": "2001", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='groves-bros' AND approved AND profile IS NULL;
UPDATE companies SET description='Guerrilla Graphix operates from Albuquerque, New Mexico, in the city''s Nob Hill district. The small business offers a diverse selection of over 1,000 gift items for retail and wholesale customers, alongside custom printing and design services.

The company provides graphic design, branding, pre-press layout, and logo development, and produces custom screen printing, embroidery, and large-format digital printing on apparel such as T-shirts, hoodies, hats, bandanas, aprons, tote bags, team jerseys, and uniforms. It also runs an online store featuring pop-culture and New Mexico-themed merchandise, and offers wholesale contract printing services for resellers.

Customers include retail shoppers, wholesale buyers, and organizations seeking custom branded apparel. The wholesale program supplies giftware and apparel to resellers, while the contract printing side serves teams, businesses, and local groups needing uniforms or promotional items.

