UPDATE companies SET description='Hinzman Millworks Inc. is a fifth-generation, family-owned hardwood manufacturing company based in West Union, West Virginia. The business has been passed down through five generations of the Hinzman family, building a legacy in Appalachian hardwood processing.

The company specializes in producing premium American white oak staves for bourbon barrels, with expanding capacity for wine barrel staves. Its operations encompass timber procurement, sawmill processing, stave manufacturing, kiln drying, and custom lumber milling. Product lines include barrel staves, dimensional lumber, cants, railroad ties, construction-grade hardwood, and coal mine cribbing. The facility employs sustainable forestry practices and selective harvesting methods to ensure long-term forest health.

Hinzman Millworks serves cooperages, distilleries, wineries, construction firms, mining operations, and infrastructure projects. Its white oak staves are used by major bourbon producers such as Buffalo Trace, and the company has supplied West Virginia Great Barrel Co. International markets include cooperages, flooring manufacturers, and furniture makers in Europe, Asia, and South America, with kiln-dried products prepared to meet export moisture standards.

The company emphasizes craftsmanship, sustainability, and operational efficiency as core differentiators. Direct partnerships with local landowners and loggers secure a consistent supply of tight-grain Appalachian oak while supporting the regional economy. Ongoing investments in kiln drying and export preparation aim to broaden the company''s reach in global value-added hardwood markets.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Barrel Stave Production", "Specialty Lumber Products", "Custom Lumber Milling", "Timber Procurement", "Kiln Drying", "Sustainable Timber Harvesting", "Export Preparation", "Sawmill Operations", "Railroad Tie Manufacturing", "Coal Mine Cribbing Manufacturing"], "industries": ["Cooperage", "Bourbon Production", "Wine Production", "Construction", "Mining", "Infrastructure", "Flooring Manufacturing", "Furniture Manufacturing", "International Export Markets"], "materials": ["White Oak", "Appalachian Hardwoods", "Tight-grain Appalachian Oak"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Fifth-generation family-owned heritage in Appalachian hardwood manufacturing", "Sustainable forestry practices with selective harvesting methods", "Kiln-dried staves meeting international export moisture standards", "Direct timber procurement partnerships with local landowners and loggers", "Supplier to major bourbon producers including Buffalo Trace"], "facts_used": ["Fifth-generation family-owned hardwood manufacturing company in West Union, WV -> /", "Specializes in white oak staves for bourbon and wine barrels -> /", "Products include barrel staves, lumber, cants, railroad ties, construction-grade hardwood, coal mine cribbing -> /", "Supplies staves to Buffalo Trace -> /about-us", "Sustainable forestry practices with selective harvesting -> /services", "Kiln drying process for export readiness -> /services", "Timber procurement partnerships with local landowners and loggers -> /services", "Export markets in Europe, Asia, South America -> /services", "Testimonial from West Virginia Great Barrel Co. -> /", "Commitment to craftsmanship, sustainability, operational efficiency -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Hinzman Millworks Inc. is a fifth-generation, family-owned hardwood manufacturing company located in West Union, West Virginia.", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Family-owned"]}'::jsonb, updated_at=now() WHERE slug='hinzman-millworks-inc' AND approved AND profile IS NULL;
UPDATE companies SET description='Hobbs Medical is a privately held company founded in 1984 and based in Stafford Springs, Connecticut. It was among the first to specialize in the design and manufacture of custom diagnostic and therapeutic accessories for the gastrointestinal and pulmonary endoscopy markets.

