UPDATE companies SET description='Horizon Nut Company, founded in 2007 in Lost Hills, California, operates as a grower-owned pistachio processing facility. The business is owned by 45 family-farmer members who supply the crop, and it is led by a group of industry pioneers with decades of experience in California pistachio production.

The company provides hulling, drying, and full pistachio processing services for its member growers. It is currently expanding its operations to meet rapidly growing demand, with a stated goal of reaching 100 million pounds of annual processing capacity. The facility handles the entire post-harvest process from farm to table.

Horizon Nut serves pistachio growers throughout California’s Central Valley, which produces 99 percent of the U.S. pistachio crop. Its customer base consists of the 45 grower-owners, who are hands-on farming operations, and the company positions itself as a dedicated partner for moving their crop from harvest to market.

The cooperative model is central to Horizon Nut’s identity: because the growers own the processor, the company says it never compromises on quality and processes pistachios “the way farmers intended them to be.” The structure aligns processing decisions directly with the interests of the farming families who supply the raw product.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Pistachio Processing", "Hulling", "Drying"], "industries": ["Agriculture"], "materials": ["Pistachios"], "equipment": [], "volume": "Target capacity of 100 million pounds annually", "lead_time": "", "tolerances": "", "built_on": ["100% grower-owned cooperative structure", "Target processing capacity of 100 million pounds annually", "Hulling and drying services for member growers", "Grower group of 45 family-farmer owners", "Processing decisions aligned with farmer interests"], "facts_used": ["Founded in 2007 -> db", "Headquarters in Lost Hills, California -> db", "Grower-owned with 45 grower-members -> page ''/''", "Pistachio processing, hulling, and drying capabilities -> db and page ''/''", "Target processing capacity of 100 million pounds annually -> page ''/''", "Serves pistachio growers across California''s Central Valley -> page ''/''", "California produces 99% of U.S. pistachio yield -> page ''/''", "Company led by diverse group of industry pioneers -> page ''/''", "Never compromise quality pledge -> page ''/''", "Processing pistachios the way farmers intended -> page ''/''"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Horizon Nut Company is a grower-owned, California grown pistachio processing operation", "founded_year": "2007", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Family-owned"]}'::jsonb, updated_at=now() WHERE slug='horizon-nut-company' AND approved AND profile IS NULL;
UPDATE companies SET description='The company began as a full-package operation offering strategy, design, development, and manufacturing services for fashion brands.

The firm operates four verticals: strategy, design, development, and manufacturing. Its vertically integrated structure takes concepts through creative ideation, technical design, pattern making, sourcing, sampling, and prototype development to finished garments and accessories. Production runs range from 150 to 2,000 units, with most garments produced in Los Angeles while leveraging a global partner network. The company works with over 400 domestic and international brands.

Clients span activewear, athleisure, contemporary, swimwear, sportswear, and streetwear categories. The company serves independent designers, in-house creative teams, and established brands seeking end-to-end production support, from brand identity and collection design through to final manufacturing.

The company emphasizes a vertically integrated model that streamlines every stage, sustainable practices across sourcing, dyeing, and packaging, and a focus on craftsmanship over quantity. It positions itself on low minimum orders, quick turnaround times, and transparent pricing to help emerging brands avoid the pitfalls of overseas production.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Strategy and market research", "Brand identity and collection design", "Technical design", "Pattern making", "Sourcing", "Sampling", "Prototype development", "Garment manufacturing", "Accessory manufacturing", "Creative ideation", "Blueprint Program (market research, strategic planning, brand identity, collection design)"], "industries": ["Activewear", "Athleisure", "Contemporary", "Swimwear", "Sportswear", "Streetwear", "Fashion brands"], "materials": [], "equipment": [], "volume": "150 to 2,000 units", "lead_time": "Days for concept to finished garment", "tolerances": "", "built_on": ["Vertically integrated design, development, and manufacturing in Los Angeles", "Production runs from 150 units with global partner network", "Sustainable practices across sourcing, dyeing, packaging", "Transparent pricing and quick turnaround for emerging brands", "Craftsmanship and quality over fast-fashion volume"], "facts_used": ["Founded 2017 -> db", "Headquarters Los Angeles, California -> db and page", "Founder Ari leads design team -> page", "Four verticals: strategy, design, development, manufacturing -> page", "Vertically integrated structure -> page", "Production runs 150-2000 units -> page", "Works with over 400 domestic and global brands -> page", "Industries: activewear, athleisure, contemporary, swimwear, sportswear, streetwear -> page", "Services: brand identity, collection design, market research, strategic planning, technical design, pattern making, sourcing, sampling, prototype development -> page", "Sustainable practices across sourcing, dyeing, packaging -> page"